<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Compras';$rows=$pdo->query('SELECT c.*,f.nome fornecedor,u.nome usuario_nome FROM compras c JOIN fornecedores f ON f.id=c.fornecedor_id JOIN usuarios u ON u.id=c.usuario_id ORDER BY c.id DESC LIMIT 300')->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Compras</h1><a class="btn primary" href="form.php">＋ Nova compra</a></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Fornecedor</th><th>Documento</th><th>Total</th><th>Parcelado</th><th>Usuário</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=date_br($r['data_compra'])?></td><td><?=e($r['fornecedor'])?></td><td><?=e($r['numero_documento'])?></td><td><?=money($r['total'])?></td><td><?=($r['parcelado']?'Sim':'Não')?></td><td><?=e($r['usuario_nome'])?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="empty">Nenhuma compra.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
